614-/// A row saying how many previous items there are, which expands into a
615-/// scrollable accordion of every one of them, oldest first, each headed by
616-/// its status and prompt and opening onto its prompt and output. Previous
617-/// tasks and previous answers are each one of these.
        let theme = cx.theme();
        let content = if count == 0 {
            div()
                .p_4()
                .text_color(theme.muted_foreground)
                .child("No output.")
                .into_any_element()
        } else {
            let this = cx.entity().downgrade();
            let open = self.file_opener(cx);
            let border = theme.border;
            let rows = list(self.output_list.clone(), move |row_ix, _, cx| {
                let Some(this) = this.upgrade() else {
                    return div().into_any_element();
                };
                let this = this.read(cx);
                let Some(task) = this.tasks.get(task_ix) else {
                    return div().into_any_element();
                };
                let rows = task.reply.rows();
                let Some(row) = rows.get(row_ix) else {
                    return div().into_any_element();
                };
                let project_dir = ProjectDirectory::get(cx);
                div()
                    .when(row_ix > 0, |row| row.border_t_1().border_color(border))
                    .child(output_row(
                        task_ix,
                        &task.reply,
                        row_ix,
                        row,
                        Some(&open),
                        project_dir.as_deref(),
                        cx,
                    ))
                    .into_any_element()
            })
